require "spec_helper"
require "timekeeping_relay"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "a stale_generation refusal from the fake projection leaves every row unsent until the generation is accepted" do
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    projection = TimekeepingContract::FakeRelay.new(source: timekeeping)
    generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION

    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      answer = projection.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                               headers: { "Authorization" => "Bearer #{credential}", "Idempotency-Key" => idempotency_key },
                               body: batch)
      TimekeepingRelay::Response.new(status: answer.status, body: answer.body)
    end

    rows = [5, 9].map do |position|
      { "generation" => generation, "outbox_position" => position,
        "entry" => { "id" => 100 + position, "company_id" => 1, "version" => 1 } }
    end
    marked = []
    source = Object.new
    source.define_singleton_method(:unsent_after) do |position, limit|
      rows.select { |row| row["outbox_position"] > position && !marked.include?(row["outbox_position"]) }.first(limit)
    end
    source.define_singleton_method(:mark_sent) { |positions| marked.concat(positions) }

    relay = described_class.new(source:, endpoint:)

    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    projection.generation = generation + 1
    expect(relay.deliver(limit: 10)).to eq(sent: 0, last_position: nil)
    expect(marked).to be_empty
    expect(projection.projected_entry(105)).to be_nil

    projection.generation = generation
    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 9)
    expect(marked).to eq([5, 9])
    expect(projection.projected_entry(109)).to include("id" => 109)
  end
end

require "spec_helper"
require "timekeeping_relay"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "a resend after a lost mark leaves the fake projection unchanged and then marks the rows sent" do
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    projection = TimekeepingContract::FakeRelay.new(source: timekeeping)
    generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION
    posts = []

    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      posts << idempotency_key
      answer = projection.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                               headers: { "Authorization" => "Bearer #{credential}", "Idempotency-Key" => idempotency_key },
                               body: batch)
      TimekeepingRelay::Response.new(status: answer.status, body: answer.body)
    end

    rows = [{ "generation" => generation, "outbox_position" => 3,
              "entry" => { "id" => 77, "company_id" => 1, "version" => 2, "note" => "first" } }]
    marked = []
    lose_next_mark = true
    source = Object.new
    source.define_singleton_method(:unsent_after) do |position, limit|
      rows.select { |row| row["outbox_position"] > position && !marked.include?(row["outbox_position"]) }.first(limit)
    end
    source.define_singleton_method(:mark_sent) do |positions|
      if lose_next_mark
        lose_next_mark = false
        raise IOError, "outbox database went away"
      end
      marked.concat(positions)
    end

    relay = described_class.new(source:, endpoint:)

    # "resends after an outage, and survives duplicates"
    expect { relay.deliver(limit: 10) }.to raise_error(IOError)
    projected_before = projection.projected_entry(77)

    expect(relay.deliver(limit: 10)).to eq(sent: 1, last_position: 3)
    expect(posts.size).to eq(2)
    expect(posts.uniq.size).to eq(1)
    expect(projection.projected_entry(77)).to eq(projected_before)
    expect(marked).to eq([3])
  end
end

require "spec_helper"
require "timekeeping_relay"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "two outbox sources with the same positions but different entries both reach the fake projection" do
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "timekeeping", operations: ["deliver"])
    projection = TimekeepingContract::FakeRelay.new(source: timekeeping)
    generation = TimekeepingContract::FakeTimekeeping::INITIAL_GENERATION

    endpoint = Object.new
    endpoint.define_singleton_method(:deliver) do |batch, idempotency_key:|
      answer = projection.call("POST", "/internal/v1/timekeeping/entry-snapshots",
                               headers: { "Authorization" => "Bearer #{credential}", "Idempotency-Key" => idempotency_key },
                               body: batch)
      TimekeepingRelay::Response.new(status: answer.status, body: answer.body)
    end

    build_source = lambda do |entry_id|
      rows = [{ "generation" => generation, "outbox_position" => 1,
                "entry" => { "id" => entry_id, "company_id" => 1, "version" => 1 } }]
      marked = []
      source = Object.new
      source.define_singleton_method(:unsent_after) do |position, limit|
        rows.select { |row| row["outbox_position"] > position && !marked.include?(row["outbox_position"]) }.first(limit)
      end
      source.define_singleton_method(:mark_sent) { |positions| marked.concat(positions) }
      source
    end

    # Each application numbers its own outbox, so equal positions must not
    # make the consumer replay one batch's answer for the other.
    expect(described_class.new(source: build_source.call(301), endpoint:).deliver(limit: 10)).to eq(sent: 1, last_position: 1)
    expect(described_class.new(source: build_source.call(302), endpoint:).deliver(limit: 10)).to eq(sent: 1, last_position: 1)

    expect(projection.projected_entry(301)).to include("id" => 301)
    expect(projection.projected_entry(302)).to include("id" => 302)
  end
end
